try {
  const rawUrl = window.location.href;
  const rawPrefix = 'file:///path/to/user/Calibre%20书库';
  const normalizedUrl = decodeURIComponent(rawUrl);
  const normalizedPrefix = decodeURIComponent(rawPrefix);
  const urlOk = normalizedUrl.startsWith(normalizedPrefix);
  const main = document.querySelector('.calibreMain');
  const contents = document.querySelectorAll('.calibreEbookContent');
  const content = contents.length === 1 ? contents[0] : null;
  if (!urlOk || !main || !content) {
    window.alert(`渲染未执行\nURL前缀匹配：${urlOk}\n.calibreMain存在：${Boolean(main)}\n.calibreEbookContent数量：${contents.length}`);
  } else {
    const styleId = 'automa-calibre-reader-style-v3';
    let style = document.getElementById(styleId);
    if (!style) {
      style = document.createElement('style');
      style.id = styleId;
      document.head.appendChild(style);
    }
    style.textContent = `
      body > *:not(:has(.calibreEbookContent)) { display: none !important; }
      body > *:has(.calibreEbookContent) { display: block !important; }
      body > *:has(.calibreEbookContent) *:not(:has(.calibreEbookContent)):not(.calibreEbookContent) { display: none !important; }
      .calibreEbookContent {
        display: block !important;
        width: 80vw !important;
        max-width: none !important;
        min-height: 100vh;
        margin-left: auto !important;
        margin-right: auto !important;
        padding: 2rem 3rem;
        box-sizing: border-box;
        color: #111 !important;
        background: #fff !important;
      }
    `;
    const safeUrl = rawUrl.length > 240 ? rawUrl.slice(0, 240) + '…' : rawUrl;
    window.alert(`渲染样式已注入\nURL前缀匹配：${urlOk}\n.calibreEbookContent数量：${contents.length}\n宽度：80vw\n背景：白色\n当前URL：${safeUrl}`);
  }
} catch (error) {
  window.alert(`渲染异常：${String(error?.message || error).slice(0, 240)}`);
}
automaNextBlock();
